{
  "items": [
    {
      "name": "le_csSup_iff'",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : ConditionallyCompleteLinearOrderBot α] {s : Set α} {a : α},\n  BddAbove s → (a ≤ sSup s ↔ ∀ b ∈ upperBounds s, a ≤ b)"
    },
    {
      "name": "csSup_le'",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : ConditionallyCompleteLinearOrderBot α] {s : Set α} {a : α}, a ∈ upperBounds s → sSup s ≤ a"
    },
    {
      "name": "ConditionallyCompleteLattice.csSup_le",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Defs",
      "kind": "theorem",
      "type": "∀ {α : Type u_5} [self : ConditionallyCompleteLattice α] (s : Set α) (a : α),\n  s.Nonempty → a ∈ upperBounds s → sSup s ≤ a"
    },
    {
      "name": "isLUB_csSup'",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : ConditionallyCompleteLinearOrderBot α] {s : Set α}, BddAbove s → IsLUB s (sSup s)"
    },
    {
      "name": "IsClosed.isGreatest_csSup",
      "module_name": "Mathlib.Topology.Order.Monotone",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : ConditionallyCompleteLinearOrder α] [inst_1 : TopologicalSpace α] [OrderTopology α]\n  {s : Set α}, IsClosed s → s.Nonempty → BddAbove s → IsGreatest s (sSup s)"
    }
  ]
}
